public struct ImageRequest: Hashable, Sendable {
    public let url: URL
    public var targetSize: CGSize?          // in pixels
    public var processors: [String] = []    // identifiers
    public var priority: Priority = .normal
}

public actor ImagePipeline {
    public func image(for request: ImageRequest) async throws -> UIImage {
        if let img = memory[request] { return img }
        let data = try await diskData(request.url) ?? coalescedDownload(request.url)
        let img = try await decode(data, to: request.targetSize)   // off-main, ImageIO
        memory[request] = img
        return img
    }
}
